package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class UnifiedSearchTest {
 UnifiedSearch.Entry entry(String id,String type,String title,String detail){return new UnifiedSearch.Entry(id,type,"content://test/"+id,title,detail);}
 @Test public void artistAndAccentsAndRanking(){UnifiedSearch.Entry artist=entry("a","audio","Evidências","Chitãozinho e Xororó"),exact=entry("b","audio","Evidências ao vivo","");assertEquals(1,UnifiedSearch.find(Arrays.asList(artist,exact),"chitaozinho xororo",0).size());assertSame(artist,UnifiedSearch.find(Arrays.asList(exact,artist),"evidencias",0).get(0));assertTrue(UnifiedSearch.find(Arrays.asList(artist),"chitaozinho inexistente",0).isEmpty());}
 @Test public void filtersDoNotInventVideoFavoritesOrNoteResume(){UnifiedSearch.Entry a=entry("a","audio","Áudio",""),v=entry("v","video","Vídeo",""),n=entry("n","note","PDF","Boleto de outubro");a.favorite=true;a.seen=10;v.favorite=true;n.seen=20;List<UnifiedSearch.Entry> all=Arrays.asList(a,v,n);assertEquals(Arrays.asList(a),UnifiedSearch.find(all,"",6));assertEquals(Arrays.asList(a),UnifiedSearch.find(all,"",7));assertEquals(Arrays.asList(n),UnifiedSearch.find(all,"boleto outubro",5));assertEquals(Arrays.asList(v),UnifiedSearch.find(all,"",2));}
 @Test public void mergeRetainsPointFavoriteAndSeparateNotesAndFiles(){UnifiedSearch.Entry a=entry("1","audio","One",""),b=entry("2","audio","Other",""),saved=entry("1","audio","One","");saved.seen=20;saved.position=12000;a.favorite=true;UnifiedSearch.Entry n=entry("n1","note","One","first"),n2=entry("n2","note","One","second");n2=new UnifiedSearch.Entry("n2","note",n.uri,"One","second");List<UnifiedSearch.Entry> merged=UnifiedSearch.merge(Arrays.asList(a,b,saved,n,n2));assertEquals(4,merged.size());assertEquals(12000,merged.get(0).position);assertTrue(merged.get(0).favorite);}
 @Test public void onlyKnownMediaStoreAliasesMerge(){assertEquals(UnifiedSearch.canonical("content://media/external/audio/media/12"),UnifiedSearch.canonical("content://media/external_primary/audio/media/12"));assertNotEquals(UnifiedSearch.canonical("content://other/external_primary/12"),UnifiedSearch.canonical("content://other/external/12"));}
 @Test public void explicitWorkspaceCommandsAndSearchSafety(){WorkspaceVoice c=WorkspaceVoice.parse("Onda, abra minha coleção Estudo");assertEquals("collection",c.action);assertEquals("estudo",c.query);assertEquals("video",WorkspaceVoice.parse("continue o último vídeo").type);assertEquals("pdf",WorkspaceVoice.parse("retome o último PDF").type);assertEquals("audio",WorkspaceVoice.parse("continue a última música").type);assertEquals("",WorkspaceVoice.parse("continue o último conteúdo").type);assertNull(WorkspaceVoice.parse("continue"));assertNull(WorkspaceVoice.parse("pesquise abra minha coleção Estudo"));assertNull(WorkspaceVoice.parse("toque as favoritas"));assertEquals("search",WorkspaceVoice.parse("busque no Onda continue o último vídeo").action);assertEquals("Fatura".toLowerCase(),WorkspaceVoice.parse("abra o PDF Fatura").query);}
}
